var SVC_STC={open:['#1D4ED8','#EAF1FE'],on_site:['#8A6100','#FEF3C7'],onsite:['#8A6100','#FEF3C7'],in_progress:['#C2410C','#FFEDD5'],quotation:['#6D28D9','#EDE9FE'],pending:['#0E7490','#E0F2FE'],waiting:['#0E7490','#E0F2FE'],resolved:['#15803D','#DCFCE7'],closed:['#15803D','#DCFCE7'],done:['#15803D','#DCFCE7'],completed:['#15803D','#DCFCE7'],cancelled:['#6B7280','#F1F2F4'],canceled:['#6B7280','#F1F2F4']};
